#include <vector>
#include <algorithm>

class Solution {
public:
    long long countIntersectingIntervalPairs(std::vector<std::vector<int>>& intervals) {
        long long n = intervals.size();
        if (n <= 1) return 0;

        long long total = n * (n - 1) / 2;
        std::vector<int> ends;
        for (auto const& iv : intervals) ends.push_back(iv[1]);
        std::sort(ends.begin(), ends.end());

        long long disjoint = 0;
        for (auto const& iv : intervals) {
            auto it = std::lower_bound(ends.begin(), ends.end(), iv[0]);
            disjoint += std::distance(ends.begin(), it);
        }
        return total - disjoint;
    }
};

import java.util.*;

class Solution {
    public long countIntersectingIntervalPairs(int[][] intervals) {
        long n = intervals.length;
        if (n <= 1) return 0;

        long total = n * (n - 1) / 2;
        int[] ends = new int[(int) n];
        for (int i = 0; i < n; i++) ends[i] = intervals[i][1];
        Arrays.sort(ends);

        long disjoint = 0;
        for (int[] iv : intervals) {
            int idx = bisectLeft(ends, iv[0]);
            disjoint += idx;
        }
        return total - disjoint;
    }

    private int bisectLeft(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (arr[mid] >= target) r = mid;
            else l = mid + 1;
        }
        return l;
    }
}

